(window.GROUP_QUIZZES=window.GROUP_QUIZZES||{})["microbiology-exam-1-microbe-human-interactions-quiz-version-2"]={"title":"Microbe-Human Interactions — Quiz 2","category":"Microbiology","exam":"Exam 1","sem":"fall-2026","questions":[{"q":"Which is the first of Koch's classic postulates?","choices":["Find the microbe in every case of the disease","Cultivate the microbe in the laboratory","Inoculate a healthy susceptible subject","Re-isolate the agent from the new host"],"answer":0,"exp":"Correct. — PAJ5200.Microbe-human-interactions(1).pptx, Slide 59"},{"q":"What distinguishes an epidemic from a pandemic?","choices":["A pandemic is global","An epidemic is global","A pandemic affects only animals","An epidemic lasts longer"],"answer":0,"exp":"Correct; an epidemic exceeds expectation in a population. — PAJ5200.Microbe-human-interactions(1).pptx, Slide 56"},{"q":"Which patient group does the lecture flag as weakened in defences, and therefore at risk?","choices":["Healthy young adults","Athletes","Those whose resident flora remain fully intact","The elderly, young children and premature infants"],"answer":3,"exp":"Correct, alongside those on immunosuppressants. — PAJ5200.Microbe-human-interactions(1).pptx, Slide 22"},{"q":"Which does the lecture give as examples of vectors?","choices":["Airborne droplet nuclei","Mosquitoes, fleas and ticks","Soil and water sources","Fomites and vehicles"],"answer":1,"exp":"Correct, with flies and cockroaches also named. — PAJ5200.Microbe-human-interactions(1).pptx, Slide 44"},{"q":"What is a passive carrier, in the lecture's terms?","choices":["Someone recovered but still shedding","Someone such as medical or dental personnel","Someone with an obvious active infection","An animal that transmits disease"],"answer":1,"exp":"Correct — carrying the organism without being infected by it. — PAJ5200.Microbe-human-interactions(1).pptx, Slide 42"},{"q":"What distinguishes an exogenous from an endogenous infectious agent?","choices":["Exogenous is bacterial, endogenous is viral","Exogenous is nosocomial, endogenous is community","Exogenous requires a vector","Exogenous comes from outside, endogenous from within"],"answer":3,"exp":"Correct. — PAJ5200.Microbe-human-interactions(1).pptx, Slide 25"},{"q":"What does the lecture say about eliminating a zoonotic infection?","choices":["It requires only vector control","It is eliminated by vaccinating the human population alone","It cannot be eliminated without eradicating the animal reservoir","It is eliminated once human cases stop"],"answer":2,"exp":"Correct. — PAJ5200.Microbe-human-interactions(1).pptx, Slide 46"},{"q":"Which bacteria are the source of endotoxin?","choices":["Gram-negative bacteria","Gram-positive bacteria","Only spore formers","Only anaerobes"],"answer":0,"exp":"Correct — lipid A is part of their outer membrane lipopolysaccharide. — PAJ5200.Microbe-human-interactions(1).pptx, Slide 31"},{"q":"What does the infectious dose fifty describe?","choices":["The dose killing half of those infected","The dose at which symptoms first appear","Half the minimum number needed for infection","The dose infecting half of a given population"],"answer":3,"exp":"Correct, the standard expression of infectious dose. — PAJ5200.Microbe-human-interactions(1).pptx, Slide 27"},{"q":"Which route does the lecture class as indirect contact?","choices":["Transplacental spread","A tick bite","Airborne droplet nuclei","Kissing"],"answer":2,"exp":"Correct, along with vehicles and fomites. — PAJ5200.Microbe-human-interactions(1).pptx, Slide 48"},{"q":"What does a small infectious dose imply about an organism?","choices":["Reduced transmissibility","Greater virulence","Lower virulence","A longer incubation period"],"answer":1,"exp":"Correct, and therefore a greater degree of pathogenicity. — PAJ5200.Microbe-human-interactions(1).pptx, Slide 27"},{"q":"What does a portal of exit describe?","choices":["Where a pathogen normally lives","How a pathogen adheres to tissue","How pathogens depart the host","How pathogens enter the host"],"answer":2,"exp":"Correct. — PAJ5200.Microbe-human-interactions(1).pptx, Slide 40"},{"q":"Which does the lecture give as a nonliving reservoir?","choices":["Soil and water","Asymptomatic carriers","Mosquitoes and ticks","Medical personnel"],"answer":0,"exp":"Correct. — PAJ5200.Microbe-human-interactions(1).pptx, Slide 42"},{"q":"Which factor does the lecture list as weakening host defences?","choices":["A high morbidity rate","Immunosuppressing drugs and organ transplants","A naturally low infectious dose for the organism","Presence of resident flora"],"answer":1,"exp":"Correct, alongside age, genetic defects, stress and chronic disease. — PAJ5200.Microbe-human-interactions(1).pptx, Slide 22"},{"q":"Which example of a sequela does the lecture give?","choices":["Blindness from gonococcal conjunctivitis","Fever during acute infection","A positive blood culture","Cough during a respiratory infection"],"answer":0,"exp":"Correct, alongside polio paralysis and Lyme arthritis. — PAJ5200.Microbe-human-interactions(1).pptx, Slide 41"},{"q":"How does the lecture distinguish mortality from morbidity rate?","choices":["Mortality counts deaths, morbidity counts cases","Mortality counts cases, morbidity counts deaths","Mortality is a percentage, morbidity is absolute","They measure the same thing"],"answer":0,"exp":"Correct, both expressed per hundred thousand. — PAJ5200.Microbe-human-interactions(1).pptx, Slide 54"},{"q":"Which set matches the portals of entry the lecture lists?","choices":["Broken skin and mucous membranes only, never intact skin","Skin, gastrointestinal, respiratory, urogenital, conjunctiva","Blood, lymph, bone marrow, spleen and thymus","Only the respiratory and gastrointestinal tracts"],"answer":1,"exp":"Correct, with pregnancy and birth also named. — PAJ5200.Microbe-human-interactions(1).pptx, Slide 25"},{"q":"What trend over the last century does the lecture describe?","choices":["Both rose together","Death rate rose while morbidity fell","Death rate fell while morbidity stayed high","Both death and morbidity rates fell"],"answer":2,"exp":"Correct. — PAJ5200.Microbe-human-interactions(1).pptx, Slide 54"},{"q":"What is a fomite?","choices":["A live animal that transmits disease","A person carrying without symptoms","An airborne droplet nucleus","An inanimate object that carries infection"],"answer":3,"exp":"Correct, grouped with vehicles under indirect contact. — PAJ5200.Microbe-human-interactions(1).pptx, Slide 48"},{"q":"Which organisms does the lecture name as most commonly involved in nosocomial infection?","choices":["Staphylococci and streptococci only","Strict anaerobes and spore formers","Respiratory viruses and yeasts by themselves","Escherichia coli, Pseudomonas and Klebsiella"],"answer":3,"exp":"Correct, with staphylococci, streptococci and yeasts. — PAJ5200.Microbe-human-interactions(1).pptx, Slide 50"},{"q":"How does the lecture explain the presence of more than a hundred human genes of microbial origin?","choices":["Horizontal gene transfer","Convergent evolution","Random mutation","Laboratory contamination"],"answer":0,"exp":"Correct, from bacteria, fungi and plants over time. — PAJ5200.Microbe-human-interactions(1).pptx, Slide 5"},{"q":"Which is the most common non-human cell type in the body?","choices":["Protozoa","Bacteria","Fungi","Viruses"],"answer":1,"exp":"Correct. — PAJ5200.Microbe-human-interactions(1).pptx, Slide 4"},{"q":"What does the lecture say about the lower respiratory tract?","choices":["It is colonised by anaerobes","It has the same flora as the mouth","It is essentially sterile","It carries Neisseria meningitidis normally"],"answer":2,"exp":"Correct, and colonisation there means trouble. — PAJ5200.Microbe-human-interactions(1).pptx, Slide 16"},{"q":"How does the lecture define a reservoir of infection?","choices":["The minimum dose needed to infect","The primary habitat a pathogen originates from","The route by which a pathogen exits a host","The population currently infected"],"answer":1,"exp":"Correct; it may be living or nonliving. — PAJ5200.Microbe-human-interactions(1).pptx, Slide 42"},{"q":"How does the lecture define a nosocomial infection?","choices":["Any infection resistant to antibiotics","Any infection in an immunocompromised patient","An infection present on admission","One acquired or developing during a hospital stay"],"answer":3,"exp":"Correct, also called a hospital-acquired infection. — PAJ5200.Microbe-human-interactions(1).pptx, Slide 50"},{"q":"What does the lecture call a disease with occasional cases at irregular intervals?","choices":["Sporadic","Endemic","Epidemic","Pandemic"],"answer":0,"exp":"Correct. — PAJ5200.Microbe-human-interactions(1).pptx, Slide 56"},{"q":"What defines an endemic disease?","choices":["Prevalence rising beyond expectation","A global epidemic","Steady frequency in a particular location","Occasional cases at irregular intervals"],"answer":2,"exp":"Correct, often because the reservoir is present. — PAJ5200.Microbe-human-interactions(1).pptx, Slide 56"},{"q":"What distinguishes a superinfection from an ordinary secondary infection?","choices":["It is the first infection in the sequence of events","It follows disruption of the natural microflora","It always involves a virus","It occurs only in hospital"],"answer":1,"exp":"Correct, classically after antibiotic therapy. — PAJ5200.Microbe-human-interactions(1).pptx, Slide 36"},{"q":"Which site does the lecture say carries the highest numbers of bacteria?","choices":["Oral cavity","Upper respiratory tract","Large intestine","Skin"],"answer":2,"exp":"Correct, mainly strict or facultative anaerobes. — PAJ5200.Microbe-human-interactions(1).pptx, Slide 9"},{"q":"What do exoenzymes do, per the lecture?","choices":["Kill leukocytes directly","Prevent phagocytosis","Bind tightly to the surface of the host cell","Attack host defences to allow deeper invasion"],"answer":3,"exp":"Correct — mucinase, hyaluronidase, coagulase, kinases. — PAJ5200.Microbe-human-interactions(1).pptx, Slide 31"}]};
